/* Physics: second labs and four extra problems per chapter. Answers are computed in code so solutions always match. */
(function () {
  const R = PB.R, f = (x, s) => PB.fmt(x, s || 3), g = 9.8;
  const S = (id, label, min, max, step, value, unit, format) => ({ id: id, label: label, min: min, max: max, step: step, value: value, unit: unit, format: format });

  /* ---------------- Labs ---------------- */
  PB.addLabs('kinematics', [{ sim: 'explore', title: 'Motion graphs', desc: 'Position and velocity against time for constant acceleration. The dot marks the chosen instant; the area under v–t is the displacement.',
    tasks: ['Set a negative acceleration with positive initial velocity. When does the object turn around, and where is it then?', 'Check that the area under the v–t graph up to the dot equals the change in x.', 'Make the x–t graph a straight line. What must the acceleration be?'],
    params: { controls: [S('u', 'Initial velocity u', -10, 10, 0.5, 6, 'm/s'), S('a', 'Acceleration a', -5, 5, 0.1, -1.5, 'm/s²'), S('t', 'Instant t', 0, 10, 0.1, 4, 's')],
      plots: [{ x: [0, 10], y: 'auto', zero: false, xlabel: 't (s)', ylabel: 'x (m)', title: 'Position', curves: (v) => [{ f: (t) => v.u * t + 0.5 * v.a * t * t }], pts: (v) => [{ x: v.t, y: v.u * v.t + 0.5 * v.a * v.t * v.t }] },
        { x: [0, 10], y: 'auto', zero: false, xlabel: 't (s)', ylabel: 'v (m/s)', title: 'Velocity', curves: (v) => [{ f: (t) => v.u + v.a * t, color: 'rust' }], pts: (v) => [{ x: v.t, y: v.u + v.a * v.t }] }],
      readout: (v) => { const x = v.u * v.t + 0.5 * v.a * v.t * v.t, tt = v.a !== 0 ? -v.u / v.a : null; return [['x(t)', f(x) + ' m'], ['v(t)', f(v.u + v.a * v.t) + ' m/s'], ['turning point', tt != null && tt > 0 ? 't = ' + f(tt) + ' s, x = ' + f(v.u * tt + 0.5 * v.a * tt * tt) + ' m' : 'none']]; } } }]);

  PB.addLabs('newton', [{ sim: 'explore', title: 'Atwood machine with friction', desc: 'A block of mass m₁ on a rough table is pulled by a hanging mass m₂ over a light pulley.',
    tasks: ['Find the smallest m₂ that starts the system moving for μ = 0.3 and m₁ = 2 kg.', 'How does the tension compare with m₂g while the system accelerates?', 'With μ = 0, check that a = m₂g/(m₁ + m₂).'],
    params: { controls: [S('m1', 'Block on table m₁', 0.5, 10, 0.1, 2, 'kg'), S('m2', 'Hanging mass m₂', 0.1, 10, 0.1, 1, 'kg'), S('mu', 'Friction coefficient μ', 0, 1, 0.01, 0.3)],
      draw: (ctx, C, v, b, U) => { const x0 = b.x + 20, y0 = b.y + b.h * 0.45, w = b.w * 0.7; ctx.fillStyle = U.alpha(C.ink3, 0.25); ctx.fillRect(x0, y0, w, 10); const bw = 30 + 6 * v.m1; ctx.fillStyle = C.accent; ctx.fillRect(x0 + w * 0.3, y0 - bw * 0.6, bw, bw * 0.6); ctx.strokeStyle = C.ink2; ctx.beginPath(); ctx.moveTo(x0 + w * 0.3 + bw, y0 - bw * 0.3); ctx.lineTo(x0 + w, y0 - bw * 0.3); ctx.stroke(); ctx.beginPath(); ctx.arc(x0 + w + 8, y0, 10, 0, 7); ctx.stroke(); ctx.beginPath(); ctx.moveTo(x0 + w + 18, y0); ctx.lineTo(x0 + w + 18, y0 + 60); ctx.stroke(); const hw = 20 + 5 * v.m2; ctx.fillStyle = C.rust; ctx.fillRect(x0 + w + 18 - hw / 2, y0 + 60, hw, hw); U.text(ctx, 'm₁', x0 + w * 0.3 + bw / 2, y0 - bw * 0.25, '#fff', U.ui(12, 700), 'center'); U.text(ctx, 'm₂', x0 + w + 18, y0 + 60 + hw / 2 + 4, '#fff', U.ui(12, 700), 'center'); },
      plots: [{ x: [0, 10], y: 'auto', xlabel: 'm₂ (kg)', ylabel: 'a (m/s²)', curves: (v) => [{ f: (m) => Math.max(0, (m - v.mu * v.m1) * g / (v.m1 + m)) }], pts: (v) => [{ x: v.m2, y: Math.max(0, (v.m2 - v.mu * v.m1) * g / (v.m1 + v.m2)) }] }],
      readout: (v) => { const a = Math.max(0, (v.m2 - v.mu * v.m1) * g / (v.m1 + v.m2)); return [['acceleration', f(a) + ' m/s²'], ['tension', f(v.m2 * (g - a)) + ' N'], ['m₂g', f(v.m2 * g) + ' N'], ['moves if m₂ >', f(v.mu * v.m1) + ' kg']]; } } }]);

  PB.addLabs('energy', [{ sim: 'explore', title: 'Energy in a spring oscillator', desc: 'Kinetic, elastic potential and total energy against position for a mass on a spring, with an optional friction loss.',
    tasks: ['Where is the kinetic energy largest? Where is it zero?', 'Double the amplitude. What happens to the total energy?', 'How does stiffening the spring change the maximum speed for the same amplitude?'],
    params: { controls: [S('k', 'Spring constant k', 5, 200, 1, 50, 'N/m'), S('m', 'Mass m', 0.1, 5, 0.1, 0.5, 'kg'), S('A', 'Amplitude A', 0.05, 0.5, 0.01, 0.2, 'm'), S('x', 'Position x', -0.5, 0.5, 0.01, 0.1, 'm')],
      plots: [{ x: (v) => [-v.A * 1.2, v.A * 1.2], y: 'auto', xlabel: 'x (m)', ylabel: 'energy (J)', curves: (v) => [{ f: (x) => 0.5 * v.k * x * x, color: 'teal', label: 'elastic PE', from: -v.A, to: v.A }, { f: (x) => 0.5 * v.k * (v.A * v.A - x * x), color: 'rust', label: 'kinetic', from: -v.A, to: v.A }, { f: () => 0.5 * v.k * v.A * v.A, label: 'total', from: -v.A, to: v.A }], vlines: (v) => [{ x: Math.max(-v.A, Math.min(v.A, v.x)), label: 'x' }] }],
      readout: (v) => { const x = Math.max(-v.A, Math.min(v.A, v.x)); return [['total energy ½kA²', f(0.5 * v.k * v.A * v.A) + ' J'], ['speed at x', f(Math.sqrt(v.k / v.m * (v.A * v.A - x * x))) + ' m/s'], ['max speed Aω', f(v.A * Math.sqrt(v.k / v.m)) + ' m/s'], ['period', f(2 * Math.PI * Math.sqrt(v.m / v.k)) + ' s']]; } } }]);

  PB.addLabs('rotation', [{ sim: 'explore', title: 'Racing down a slope', desc: 'Acceleration of objects rolling without slipping, $a = g\\sin\\theta/(1 + I/mR^2)$, for different shapes.',
    tasks: ['Which shape always wins? Why does mass not matter?', 'Find the angle at which a hoop accelerates at 2 m/s².', 'What fraction of a solid sphere’s kinetic energy is rotational?'],
    params: { controls: [S('th', 'Slope angle θ', 1, 60, 1, 20, '°'), { type: 'select', id: 'k', label: 'Highlight', value: '0.4', options: [['0', 'Sliding block (no rolling)'], ['0.4', 'Solid sphere'], ['0.5', 'Solid cylinder'], ['0.6667', 'Hollow sphere'], ['1', 'Hoop']] }],
      plots: [{ x: [0, 60], y: [0, 9], xlabel: 'θ (°)', ylabel: 'a (m/s²)', curves: () => [['0', 'block', 'ink3'], ['0.4', 'solid sphere', 'teal'], ['0.5', 'cylinder', 'accent'], ['0.6667', 'hollow sphere', 'points'], ['1', 'hoop', 'rust']].map((s) => ({ f: (t) => g * Math.sin(t * Math.PI / 180) / (1 + +s[0]), color: s[2], label: s[1] })), pts: (v) => [{ x: v.th, y: g * Math.sin(v.th * Math.PI / 180) / (1 + +v.k) }] }],
      readout: (v) => { const k = +v.k; return [['acceleration', f(g * Math.sin(v.th * Math.PI / 180) / (1 + k)) + ' m/s²'], ['I/mR²', f(k)], ['rotational share of KE', f(100 * k / (1 + k)) + '%']]; } } }]);

  PB.addLabs('gravitation', [{ sim: 'explore', title: 'Inside and outside a planet', desc: 'Field strength and potential of a uniform-density planet, inside and outside. Radii in units of the planet’s radius R.',
    tasks: ['Where is g largest? How does it vary inside the planet?', 'Compare the escape speed from the surface with the circular orbit speed just above it.', 'What is the potential at the centre compared with the surface?'],
    params: { controls: [S('M', 'Planet mass', 0.1, 10, 0.1, 1, 'M⊕'), S('Rr', 'Planet radius', 0.3, 3, 0.05, 1, 'R⊕'), S('r', 'Probe distance', 0, 4, 0.01, 1.5, 'R')],
      plots: [{ x: [0, 4], y: 'auto', xlabel: 'r / R', ylabel: 'g (m/s²)', title: 'Field', curves: (v) => [{ f: (x) => 9.82 * v.M / (v.Rr * v.Rr) * (x < 1 ? x : 1 / (x * x)) }], pts: (v) => [{ x: v.r, y: 9.82 * v.M / (v.Rr * v.Rr) * (v.r < 1 ? v.r : 1 / (v.r * v.r)) }] },
        { x: [0, 4], y: 'auto', zero: false, xlabel: 'r / R', ylabel: 'V (MJ/kg)', title: 'Potential', curves: (v) => [{ f: (x) => -62.6 * v.M / v.Rr * (x < 1 ? (3 - x * x) / 2 : 1 / x), color: 'rust' }], pts: (v) => [{ x: v.r, y: -62.6 * v.M / v.Rr * (v.r < 1 ? (3 - v.r * v.r) / 2 : 1 / v.r) }] }],
      readout: (v) => [['surface g', f(9.82 * v.M / (v.Rr * v.Rr)) + ' m/s²'], ['escape speed', f(11.19 * Math.sqrt(v.M / v.Rr)) + ' km/s'], ['low orbit speed', f(7.91 * Math.sqrt(v.M / v.Rr)) + ' km/s'], ['low orbit period', f(84.4 * Math.sqrt(Math.pow(v.Rr, 3) / v.M)) + ' min']] } }]);

  PB.addLabs('oscillations', [{ sim: 'explore', title: 'Coupled pendulums and beats', desc: 'Two identical pendulums joined by a weak spring. Start one swinging and the energy sloshes back and forth between them.',
    tasks: ['With weak coupling, how long does the energy take to transfer completely?', 'Increase the coupling. What happens to the beat period?', 'Find the two normal-mode frequencies from the readout and check that the beat frequency is their difference.'],
    params: { controls: [S('w0', 'Pendulum frequency ω₀', 1, 6, 0.1, 3, 'rad/s'), S('k', 'Coupling strength κ (as a fraction of ω₀²)', 0.01, 0.5, 0.01, 0.08)],
      plots: [{ x: [0, 40], y: [-1.1, 1.1], xlabel: 't (s)', ylabel: 'displacement', curves: (v) => { const w1 = v.w0, w2 = v.w0 * Math.sqrt(1 + 2 * v.k); return [{ f: (t) => 0.5 * (Math.cos(w1 * t) + Math.cos(w2 * t)), label: 'pendulum 1', width: 1.6 }, { f: (t) => 0.5 * (Math.cos(w1 * t) - Math.cos(w2 * t)), color: 'rust', label: 'pendulum 2', width: 1.6 }]; }, n: 1600 }],
      readout: (v) => { const w1 = v.w0, w2 = v.w0 * Math.sqrt(1 + 2 * v.k); return [['in-phase mode ω₁', f(w1) + ' rad/s'], ['out-of-phase mode ω₂', f(w2) + ' rad/s'], ['full transfer time π/(ω₂ − ω₁)', f(Math.PI / (w2 - w1)) + ' s']]; } } }]);

  PB.addLabs('thermodynamics', [{ sim: 'explore', title: 'Isotherms and adiabats', desc: 'P–V curves for one mole of ideal gas expanding from the same starting point, isothermally ($PV$ = const) and adiabatically ($PV^\\gamma$ = const).',
    tasks: ['Which curve is steeper, and why?', 'Compare the work done in the two expansions to the same final volume.', 'Change γ from 5/3 (monatomic) to 7/5 (diatomic). What happens to the final temperature?'],
    params: { controls: [S('T', 'Starting temperature', 200, 800, 10, 400, 'K'), S('V2', 'Final volume', 2, 10, 0.1, 5, 'L'), { type: 'select', id: 'gam', label: 'Gas', value: '1.6667', options: [['1.6667', 'Monatomic (γ = 5/3)'], ['1.4', 'Diatomic (γ = 7/5)'], ['1.3333', 'Polyatomic (γ = 4/3)']] }],
      plots: [{ x: [1, 10], y: 'auto', xlabel: 'V (L)', ylabel: 'P (kPa)', curves: (v) => { const P1 = 8.314 * v.T / 1; return [{ f: (V) => P1 / V, label: 'isotherm' }, { f: (V) => P1 * Math.pow(1 / V, +v.gam), color: 'rust', label: 'adiabat' }]; }, vlines: (v) => [{ x: v.V2, label: 'V₂' }] }],
      readout: (v) => { const gm = +v.gam, Wi = 8.314 * v.T * Math.log(v.V2), T2 = v.T * Math.pow(1 / v.V2, gm - 1), Wa = 8.314 * (v.T - T2) / (gm - 1); return [['start', '1 mol, 1 L, ' + f(8.314 * v.T) + ' kPa'], ['isothermal work', f(Wi) + ' J'], ['adiabatic work', f(Wa) + ' J'], ['final T (adiabatic)', f(T2) + ' K']]; } } }]);

  PB.addLabs('electrostatics', [{ sim: 'explore', title: 'Charged spheres: conductor versus insulator', desc: 'Field and potential of a charge Q spread over a conducting sphere (all on the surface) or uniformly through an insulating sphere of radius R.',
    tasks: ['Where is the field zero for the conductor? Why?', 'Compare the potentials at the centre of the two spheres.', 'Outside the sphere, can you tell the two apart?'],
    params: { controls: [S('Q', 'Charge Q', 1, 50, 1, 10, 'nC'), S('R', 'Radius R', 0.02, 0.5, 0.01, 0.1, 'm')],
      plots: [{ x: [0, 4], y: 'auto', xlabel: 'r / R', ylabel: 'E (kV/m)', title: 'Field', curves: (v) => { const E0 = 8.988e9 * v.Q * 1e-9 / (v.R * v.R) / 1000; return [{ f: (x) => (x < 1 ? 0 : E0 / (x * x)), label: 'conductor' }, { f: (x) => (x < 1 ? E0 * x : E0 / (x * x)), color: 'rust', label: 'insulator', dash: [5, 4] }]; } },
        { x: [0, 4], y: 'auto', xlabel: 'r / R', ylabel: 'V (kV)', title: 'Potential', curves: (v) => { const V0 = 8.988e9 * v.Q * 1e-9 / v.R / 1000; return [{ f: (x) => (x < 1 ? V0 : V0 / x), label: 'conductor' }, { f: (x) => (x < 1 ? V0 * (3 - x * x) / 2 : V0 / x), color: 'rust', label: 'insulator', dash: [5, 4] }]; } }],
      readout: (v) => { const k = 8.988e9, q = v.Q * 1e-9; return [['surface field', f(k * q / (v.R * v.R) / 1000) + ' kV/m'], ['surface potential', f(k * q / v.R / 1000) + ' kV'], ['centre potential (insulator)', f(1.5 * k * q / v.R / 1000) + ' kV'], ['capacitance of conductor', f(v.R / k * 1e12) + ' pF']]; } } }]);

  PB.addLabs('circuits', [{ sim: 'explore', title: 'Maximum power transfer', desc: 'A battery with EMF ε and internal resistance r drives a load R. Power in the load, terminal voltage and efficiency against R.',
    tasks: ['Find the load that takes the most power. Compare it with r.', 'What is the efficiency at maximum power?', 'Why do power stations not run at maximum power transfer?'],
    params: { controls: [S('E', 'EMF ε', 1, 24, 0.5, 12, 'V'), S('r', 'Internal resistance r', 0.1, 10, 0.1, 2, 'Ω'), S('R', 'Load R', 0.1, 30, 0.1, 5, 'Ω')],
      plots: [{ x: [0, 30], y: 'auto', xlabel: 'R (Ω)', ylabel: 'P (W)', title: 'Power in the load', curves: (v) => [{ f: (R) => v.E * v.E * R / Math.pow(R + v.r, 2) }], pts: (v) => [{ x: v.R, y: v.E * v.E * v.R / Math.pow(v.R + v.r, 2) }], vlines: (v) => [{ x: v.r, label: 'R = r' }] },
        { x: [0, 30], y: [0, 1], xlabel: 'R (Ω)', ylabel: 'efficiency', title: 'Efficiency', curves: (v) => [{ f: (R) => R / (R + v.r), color: 'teal' }], pts: (v) => [{ x: v.R, y: v.R / (v.R + v.r) }] }],
      readout: (v) => { const I = v.E / (v.R + v.r); return [['current', f(I) + ' A'], ['terminal voltage', f(I * v.R) + ' V'], ['power in load', f(I * I * v.R) + ' W'], ['maximum possible', f(v.E * v.E / (4 * v.r)) + ' W at R = r']]; } } }]);

  PB.addLabs('wave-optics', [{ sim: 'explore', title: 'Thin-film colours', desc: 'Reflectance of a soap or oil film of refractive index n and thickness d against wavelength, with the colour you would see. One reflection has a phase flip, so maxima need $2nd = (m + \\tfrac12)\\lambda$.',
    tasks: ['Make the film very thin (under 50 nm). Why does it look black?', 'Find the thickness that reflects strongly at 550 nm (first order).', 'Increase the thickness to 2000 nm. Why do the colours wash out?'],
    params: { controls: [S('d', 'Thickness d', 0, 1500, 5, 300, 'nm'), S('n', 'Film index n', 1.2, 1.8, 0.01, 1.33)],
      draw: (ctx, C, v, b, U) => { let r = 0, gg = 0, bb = 0, tot = 0; for (let l = 380; l <= 780; l += 5) { const I = Math.pow(Math.sin(2 * Math.PI * v.n * v.d / l), 2); const c = U.wl2rgb(l); r += c[0] * I; gg += c[1] * I; bb += c[2] * I; tot += 1; } const k = 2.4 / tot; ctx.fillStyle = 'rgb(' + Math.min(255, r * k) + ',' + Math.min(255, gg * k) + ',' + Math.min(255, bb * k) + ')'; ctx.beginPath(); ctx.arc(b.x + b.w / 2, b.y + b.h / 2 - 10, Math.min(b.w, b.h) * 0.32, 0, 7); ctx.fill(); U.text(ctx, 'reflected colour', b.x + b.w / 2, b.y + b.h - 12, C.ink2, U.ui(11), 'center'); },
      picFrac: 0.32,
      plots: [{ x: [380, 780], y: [0, 1.05], xlabel: 'λ (nm)', ylabel: 'relative reflectance', curves: (v) => [{ f: (l) => Math.pow(Math.sin(2 * Math.PI * v.n * v.d / l), 2) }] }],
      readout: (v) => [['optical path 2nd', f(2 * v.n * v.d) + ' nm'], ['first-order max at', v.d > 0 ? f(4 * v.n * v.d) + ' nm' : '—'], ['second-order max at', v.d > 0 ? f(4 * v.n * v.d / 3) + ' nm' : '—']] } }]);

  PB.addLabs('nuclear', [{ sim: 'explore', title: 'The binding energy curve', desc: 'Binding energy per nucleon from the semi-empirical mass formula, for the most stable Z at each mass number, with its five terms.',
    tasks: ['Find the peak of the curve. Which element sits there?', 'Which term makes heavy nuclei less tightly bound?', 'Estimate the energy released when a uranium-236 nucleus splits into two equal halves.'],
    params: { controls: [S('A', 'Mass number A', 4, 260, 1, 56)],
      init: (v) => { v.semf = (A) => { const Z = Math.round(A / (1.98 + 0.0155 * Math.pow(A, 2 / 3))), N = A - Z; const d = (Z % 2 === 0 && N % 2 === 0) ? 12 / Math.sqrt(A) : (Z % 2 === 1 && N % 2 === 1) ? -12 / Math.sqrt(A) : 0; const B = 15.8 * A - 18.3 * Math.pow(A, 2 / 3) - 0.714 * Z * (Z - 1) / Math.pow(A, 1 / 3) - 23.2 * Math.pow(A - 2 * Z, 2) / A + d; return { Z: Z, B: B }; }; },
      plots: [{ x: [4, 260], y: [0, 9.5], xlabel: 'A', ylabel: 'B/A (MeV)', curves: (v) => [{ f: (A) => { const s = v.semf(Math.round(A)); return s.B / Math.round(A); } }], pts: (v) => [{ x: v.A, y: v.semf(v.A).B / v.A }], n: 256 }],
      readout: (v) => { const s = v.semf(v.A), A = v.A, Z = s.Z; return [['most stable Z', String(Z)], ['B/A', f(s.B / A) + ' MeV'], ['volume term', f(15.8 * A) + ' MeV'], ['surface term', '−' + f(18.3 * Math.pow(A, 2 / 3)) + ' MeV'], ['Coulomb term', '−' + f(0.714 * Z * (Z - 1) / Math.pow(A, 1 / 3)) + ' MeV'], ['asymmetry term', '−' + f(23.2 * Math.pow(A - 2 * Z, 2) / A) + ' MeV']]; } } }]);

  PB.addLabs('experimental', [{ sim: 'explore', title: 'Random error and the standard error', desc: 'Repeat a measurement N times with random scatter σ. The histogram shows the readings; the mean gets better as $\\sigma/\\sqrt N$.',
    tasks: ['With N = 10, how far is the mean typically from the true value 9.81?', 'Quadruple N. By what factor does the standard error shrink?', 'Why can averaging never remove a systematic error?'],
    params: { controls: [S('N', 'Number of readings N', 2, 400, 1, 20), S('s', 'Scatter σ', 0.01, 1, 0.01, 0.2, 'm/s²'), S('sys', 'Systematic offset', -0.5, 0.5, 0.01, 0, 'm/s²')],
      buttons: [{ label: 'Take new readings', primary: true, action: (v) => { v.seed = Math.random(); } }],
      init: (v) => { v.seed = Math.random(); },
      draw: (ctx, C, v, b, U) => {
        let s = Math.floor(v.seed * 1e9) || 1; const rnd = () => { s = (s * 16807) % 2147483647; return s / 2147483647; };
        const xs = []; for (let i = 0; i < v.N; i++) { const u1 = rnd() || 1e-9, u2 = rnd(); xs.push(9.81 + v.sys + v.s * Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2)); }
        const mean = xs.reduce((a, x) => a + x, 0) / xs.length, sd = Math.sqrt(xs.reduce((a, x) => a + (x - mean) * (x - mean), 0) / Math.max(1, xs.length - 1));
        v.stats = { mean: mean, sd: sd, se: sd / Math.sqrt(xs.length) };
        const lo = 9.81 - 3.2, hi = 9.81 + 3.2, bins = 64, cnt = new Array(bins).fill(0);
        const L = 9.81 - 4 * Math.max(v.s, 0.05) - 0.5, H = 9.81 + 4 * Math.max(v.s, 0.05) + 0.5;
        xs.forEach((x) => { const k = Math.floor((x - L) / (H - L) * bins); if (k >= 0 && k < bins) cnt[k]++; });
        const pb = { x: b.x + 50, y: b.y + 18, w: b.w - 66, h: b.h - 50 }, mx = Math.max(...cnt, 1);
        const m = U.frame(ctx, C, pb, [L, H], [0, mx * 1.15], { xlabel: 'reading (m/s²)', ylabel: 'count', ny: 3 });
        cnt.forEach((c, k) => { const x0 = m.X(L + (H - L) * k / bins), x1 = m.X(L + (H - L) * (k + 1) / bins); ctx.fillStyle = U.alpha(C.accent, 0.7); ctx.fillRect(x0, m.Y(c), x1 - x0 - 1, m.Y(0) - m.Y(c)); });
        [[9.81, C.good, 'true'], [mean, C.rust, 'mean']].forEach((q) => { ctx.strokeStyle = q[1]; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(m.X(q[0]), pb.y); ctx.lineTo(m.X(q[0]), pb.y + pb.h); ctx.stroke(); U.text(ctx, q[2], m.X(q[0]) + 4, pb.y + (q[2] === 'true' ? 12 : 26), q[1], U.ui(11, 700)); });
        void lo; void hi;
      },
      readout: (v) => { const s = v.stats || { mean: 0, sd: 0, se: 0 }; return [['mean', f(s.mean, 4) + ' m/s²'], ['standard deviation', f(s.sd) + ' m/s²'], ['standard error σ/√N', f(s.se) + ' m/s²'], ['result', f(s.mean, 4) + ' ± ' + f(s.se, 2)]]; } } }]);

  /* ---------------- Extra problems ---------------- */
  const X = PB.addProblems;
  X('toolkit', [
    { level: 'concept', type: 'mcq', title: 'Significant figures', q: R`<p>A length is measured as 0.004020 m. How many significant figures does it have?</p>`, options: ['3', '4', '6', '7'], answer: 1, hints: [R`Leading zeros do not count; trailing zeros after the decimal point do.`], solution: R`<p>4: the digits 4, 0, 2, 0.</p>` },
    { level: 'core', type: 'num', title: 'Pendulum by dimensions', q: R`<p>A pendulum's period depends only on $L$ and $g$. A 1.0 m pendulum has period 2.0 s. What is the period of a 2.5 m pendulum?</p>`, answer: 2 * Math.sqrt(2.5), tol: 0.01, unit: 's', hints: [R`$T \propto \sqrt{L/g}$.`], solution: R`<p>$T = 2.0\sqrt{2.5} = ${f(2 * Math.sqrt(2.5))}$ s.</p>` },
    { level: 'core', type: 'num', title: 'Small-angle error', q: R`<p>Using $\sin\theta \approx \theta$ for $\theta = 20^\circ$, what is the percentage error?</p>`, answer: 100 * ((20 * Math.PI / 180) / Math.sin(20 * Math.PI / 180) - 1), tol: 0.02, unit: '%', hints: [R`Compare 0.3491 with $\sin20^\circ$.`], solution: R`<p>$0.3491/0.3420 - 1 = ${f(100 * ((20 * Math.PI / 180) / Math.sin(20 * Math.PI / 180) - 1))}\%$.</p>` },
    { level: 'olympiad', type: 'num', title: 'Raindrop speed', q: R`<p>A raindrop's terminal speed depends on its radius $r$, $g$, and air density $\rho$ and water density $\rho_w$ through quadratic drag: $v \sim \sqrt{gr\rho_w/\rho}$. Estimate $v$ for $r = 1$ mm, $\rho_w/\rho = 830$, in m/s (take the dimensionless constant as 1).</p>`, answer: Math.sqrt(9.8 * 0.001 * 830), tol: 0.02, unit: 'm/s', hints: [R`Plug in.`], solution: R`<p>$\sqrt{9.8\times0.001\times830} = ${f(Math.sqrt(9.8 * 0.001 * 830))}$ m/s; real 2 mm drops fall at about 6.5 m/s.</p>` }
  ]);
  X('kinematics', [
    { level: 'concept', type: 'mcq', title: 'Area under v–t', q: R`<p>What does the area under a velocity–time graph represent?</p>`, options: ['Acceleration', 'Displacement', 'Speed', 'Jerk'], answer: 1, hints: [R`$\int v\,dt$.`], solution: R`<p>Displacement.</p>` },
    { level: 'core', type: 'num', title: 'Braking distance', q: R`<p>A car at 25 m/s brakes at 6.0 m/s². How far does it travel before stopping?</p>`, answer: 625 / 12, tol: 0.01, unit: 'm', hints: [R`$v^2 = u^2 - 2as$.`], solution: R`<p>$s = 25^2/(2\times6) = ${f(625 / 12)}$ m.</p>` },
    { level: 'core', type: 'num', title: 'Ball thrown up', q: R`<p>A ball is thrown straight up at 18 m/s from a cliff 30 m high. How long until it hits the ground below?</p>`, answer: (18 + Math.sqrt(18 * 18 + 2 * g * 30)) / g, tol: 0.01, unit: 's', hints: [R`Solve $-30 = 18t - 4.9t^2$.`], solution: R`<p>$t = (18 + \sqrt{324 + 588})/9.8 = ${f((18 + Math.sqrt(18 * 18 + 2 * g * 30)) / g)}$ s.</p>` },
    { level: 'olympiad', type: 'num', title: 'Maximum range on a slope', q: R`<p>A projectile is launched at 20 m/s up a slope inclined at 30°. What is the maximum range along the slope? Use $R_{\max} = \dfrac{v^2}{g(1 + \sin\alpha)}$.</p>`, answer: 400 / (g * 1.5), tol: 0.01, unit: 'm', hints: [R`$\sin30^\circ = 0.5$.`], solution: R`<p>$400/(9.8\times1.5) = ${f(400 / (g * 1.5))}$ m, reached by aiming along the bisector of the slope and the vertical.</p>` }
  ]);
  X('newton', [
    { level: 'concept', type: 'mcq', title: 'Lift scale', q: R`<p>You stand on bathroom scales in a lift that is slowing down while going up. The reading is…</p>`, options: ['More than your weight', 'Less than your weight', 'Equal to your weight', 'Zero'], answer: 1, hints: [R`Acceleration points down.`], solution: R`<p>Less: $N = m(g - a)$.</p>` },
    { level: 'core', type: 'num', title: 'Atwood acceleration', q: R`<p>Masses of 3.0 kg and 5.0 kg hang over a light frictionless pulley. Find the acceleration.</p>`, answer: 2 * g / 8, tol: 0.01, unit: 'm/s²', hints: [R`$(m_2 - m_1)g/(m_1 + m_2)$.`], solution: R`<p>$2\times9.8/8 = ${f(2 * g / 8)}$ m/s².</p>` },
    { level: 'core', type: 'num', title: 'Block on an incline', q: R`<p>A block slides down a 35° slope with $\mu_k = 0.25$. Find its acceleration.</p>`, answer: g * (Math.sin(35 * Math.PI / 180) - 0.25 * Math.cos(35 * Math.PI / 180)), tol: 0.01, unit: 'm/s²', hints: [R`$g(\sin\theta - \mu\cos\theta)$.`], solution: R`<p>$9.8(0.574 - 0.205) = ${f(g * (Math.sin(35 * Math.PI / 180) - 0.25 * Math.cos(35 * Math.PI / 180)))}$ m/s².</p>` },
    { level: 'olympiad', type: 'num', title: 'Banked curve', q: R`<p>A road of radius 80 m is banked at 15°. At what speed can a car take it with no friction needed?</p>`, answer: Math.sqrt(g * 80 * Math.tan(15 * Math.PI / 180)), tol: 0.01, unit: 'm/s', hints: [R`$v^2 = gr\tan\theta$.`], solution: R`<p>$v = \sqrt{9.8\times80\times\tan15^\circ} = ${f(Math.sqrt(g * 80 * Math.tan(15 * Math.PI / 180)))}$ m/s.</p>` }
  ]);
  X('energy', [
    { level: 'concept', type: 'mcq', title: 'Work by friction', q: R`<p>A box slides to a stop. Which force did negative work on it?</p>`, options: ['Gravity', 'The normal force', 'Kinetic friction', 'None'], answer: 2, hints: [R`Which force opposes the motion?`], solution: R`<p>Friction, opposite to the displacement.</p>` },
    { level: 'core', type: 'num', title: 'Spring launch', q: R`<p>A 0.20 kg ball is fired upwards by a spring ($k = 400$ N/m) compressed 0.10 m. How high does it rise above its launch point (ignore the spring’s extension distance)?</p>`, answer: 0.5 * 400 * 0.01 / (0.2 * g), tol: 0.01, unit: 'm', hints: [R`$\tfrac12kx^2 = mgh$.`], solution: R`<p>$h = 2/(0.2\times9.8) = ${f(0.5 * 400 * 0.01 / (0.2 * g))}$ m.</p>` },
    { level: 'core', type: 'num', title: 'Power climbing', q: R`<p>A 70 kg climber gains 500 m of height in 40 minutes. What is the average useful power?</p>`, answer: 70 * g * 500 / 2400, tol: 0.01, unit: 'W', hints: [R`$mgh/t$.`], solution: R`<p>$70\times9.8\times500/2400 = ${f(70 * g * 500 / 2400)}$ W.</p>` },
    { level: 'olympiad', type: 'num', title: 'Loop the loop', q: R`<p>A bead slides without friction from rest at height $h$ into a vertical loop of radius 0.5 m. What is the minimum $h$ to stay on the track at the top?</p>`, answer: 2.5 * 0.5, tol: 0.005, unit: 'm', hints: [R`At the top $v^2 \ge gr$.`], solution: R`<p>$mgh = mg(2r) + \tfrac12mgr$, so $h = 2.5r = 1.25$ m.</p>` }
  ]);
  X('momentum', [
    { level: 'concept', type: 'mcq', title: 'Elastic collision', q: R`<p>A moving ball hits an identical stationary ball head-on, elastically. What happens?</p>`, options: ['Both move at half speed', 'The first stops and the second moves off at the original speed', 'They stick together', 'The first bounces back'], answer: 1, hints: [R`Equal masses swap velocities.`], solution: R`<p>Velocities swap, as in Newton’s cradle.</p>` },
    { level: 'core', type: 'num', title: 'Perfectly inelastic', q: R`<p>A 1200 kg car at 15 m/s rear-ends a 900 kg car at rest; they lock together. What fraction of the kinetic energy is lost?</p>`, answer: 900 / 2100, tol: 0.01, unit: '', hints: [R`Lost fraction $= M/(m + M)$ when $M$ starts at rest.`], solution: R`<p>$900/2100 = ${f(900 / 2100)}$.</p>` },
    { level: 'core', type: 'num', title: 'Impulse', q: R`<p>A 0.145 kg baseball arrives at 40 m/s and leaves at 50 m/s in the opposite direction after 1.2 ms of contact. What is the average force?</p>`, answer: 0.145 * 90 / 0.0012, tol: 0.01, unit: 'N', hints: [R`$F = \Delta p/\Delta t$.`], solution: R`<p>$0.145\times90/0.0012 = ${f(0.145 * 90 / 0.0012)}$ N.</p>` },
    { level: 'olympiad', type: 'num', title: 'Ballistic pendulum', q: R`<p>A 10 g bullet embeds in a 2.0 kg block hanging on strings; the block rises 8.0 cm. Find the bullet's speed.</p>`, answer: (2.01 / 0.01) * Math.sqrt(2 * g * 0.08), tol: 0.01, unit: 'm/s', hints: [R`Momentum in the collision, energy afterwards.`], solution: R`<p>$v = \frac{M + m}{m}\sqrt{2gh} = 201\times1.252 = ${f((2.01 / 0.01) * Math.sqrt(2 * g * 0.08))}$ m/s.</p>` }
  ]);
  X('rotation', [
    { level: 'concept', type: 'mcq', title: 'Spinning skater', q: R`<p>A spinning skater pulls in her arms. What stays constant?</p>`, options: ['Angular velocity', 'Rotational kinetic energy', 'Angular momentum', 'Moment of inertia'], answer: 2, hints: [R`No external torque.`], solution: R`<p>Angular momentum; she spins faster and her kinetic energy rises (she does work pulling in).</p>` },
    { level: 'core', type: 'num', title: 'Flywheel energy', q: R`<p>A solid disc flywheel of mass 50 kg and radius 0.4 m spins at 3000 rpm. How much energy does it store?</p>`, answer: 0.5 * (0.5 * 50 * 0.16) * Math.pow(3000 * 2 * Math.PI / 60, 2), tol: 0.01, unit: 'J', hints: [R`$I = \tfrac12MR^2$, $\omega = 314$ rad/s.`], solution: R`<p>$E = \tfrac12(4.0)(314.2)^2 = ${f(0.5 * (0.5 * 50 * 0.16) * Math.pow(3000 * 2 * Math.PI / 60, 2))}$ J.</p>` },
    { level: 'core', type: 'num', title: 'Torque on a wrench', q: R`<p>A 120 N force is applied at 60° to a 0.30 m wrench. What is the torque?</p>`, answer: 120 * 0.3 * Math.sin(60 * Math.PI / 180), tol: 0.01, unit: 'N m', hints: [R`$\tau = rF\sin\theta$.`], solution: R`<p>${f(120 * 0.3 * Math.sin(60 * Math.PI / 180))} N m.</p>` },
    { level: 'olympiad', type: 'num', title: 'Falling rod', q: R`<p>A uniform rod of length 1.2 m pivoted at one end is released from horizontal. What is the speed of its free end as it passes vertical?</p>`, answer: Math.sqrt(3 * g * 1.2), tol: 0.01, unit: 'm/s', hints: [R`$mgL/2 = \tfrac12(\tfrac13mL^2)\omega^2$.`], solution: R`<p>$\omega = \sqrt{3g/L}$, so $v = L\omega = \sqrt{3gL} = ${f(Math.sqrt(3 * g * 1.2))}$ m/s, faster than free fall from the same height.</p>` }
  ]);
  X('gravitation', [
    { level: 'concept', type: 'mcq', title: 'Weightless astronauts', q: R`<p>Why do astronauts on the ISS feel weightless?</p>`, options: ['There is no gravity at that height', 'They and the station are in free fall together', 'The station shields gravity', 'They are too far from Earth'], answer: 1, hints: [R`g at 400 km is about 8.7 m/s².`], solution: R`<p>Everything falls together, so nothing presses on them.</p>` },
    { level: 'core', type: 'num', title: 'Geostationary radius', q: R`<p>Find the radius of a geostationary orbit, in km ($GM_E = 3.986\times10^{14}$ m³/s², sidereal day 86 164 s).</p>`, answer: Math.cbrt(3.986e14 * Math.pow(86164 / (2 * Math.PI), 2)) / 1000, tol: 0.005, unit: 'km', hints: [R`$r^3 = GMT^2/4\pi^2$.`], solution: R`<p>$r = ${f(Math.cbrt(3.986e14 * Math.pow(86164 / (2 * Math.PI), 2)) / 1000, 4)}$ km, about 35 800 km above the surface.</p>` },
    { level: 'core', type: 'num', title: 'g on Mars', q: R`<p>Mars has 0.107 Earth masses and 0.532 Earth radii. What is g at its surface?</p>`, answer: 9.81 * 0.107 / (0.532 * 0.532), tol: 0.01, unit: 'm/s²', hints: [R`$g \propto M/R^2$.`], solution: R`<p>$9.81\times0.107/0.283 = ${f(9.81 * 0.107 / (0.532 * 0.532))}$ m/s².</p>` },
    { level: 'olympiad', type: 'num', title: 'Tunnel through Earth', q: R`<p>A frictionless tunnel runs straight through uniform Earth. How long does a dropped object take to reach the other side, in minutes? ($g = 9.81$ m/s², $R = 6.37\times10^6$ m.)</p>`, answer: Math.PI * Math.sqrt(6.37e6 / 9.81) / 60, tol: 0.01, unit: 'min', hints: [R`Inside, $g(r) = gr/R$: simple harmonic motion with $\omega = \sqrt{g/R}$.`], solution: R`<p>Half a period: $\pi\sqrt{R/g} = ${f(Math.PI * Math.sqrt(6.37e6 / 9.81) / 60)}$ min, the same for any straight chord.</p>` }
  ]);
  X('oscillations', [
    { level: 'concept', type: 'mcq', title: 'Pendulum on the Moon', q: R`<p>A pendulum clock is taken to the Moon ($g/6$). Its period becomes…</p>`, options: ['6 times longer', '√6 times longer', 'unchanged', '√6 times shorter'], answer: 1, hints: [R`$T \propto 1/\sqrt g$.`], solution: R`<p>$\sqrt6 \approx 2.45$ times longer.</p>` },
    { level: 'core', type: 'num', title: 'Springs in series', q: R`<p>A 0.5 kg mass hangs from two springs of 200 N/m and 300 N/m in series. Find the period.</p>`, answer: 2 * Math.PI * Math.sqrt(0.5 / 120), tol: 0.01, unit: 's', hints: [R`$1/k = 1/200 + 1/300$.`], solution: R`<p>$k = 120$ N/m; $T = 2\pi\sqrt{0.5/120} = ${f(2 * Math.PI * Math.sqrt(0.5 / 120))}$ s.</p>` },
    { level: 'core', type: 'num', title: 'Quality factor', q: R`<p>An oscillator's amplitude falls to half in 20 cycles. Roughly what is its Q? (Energy ∝ amplitude²; $Q = 2\pi\times$ energy / energy lost per cycle.)</p>`, answer: 2 * Math.PI / (1 - Math.pow(0.5, 2 / 20)), tol: 0.03, unit: '', hints: [R`Energy falls by $0.5^{2/20}$ per cycle.`], solution: R`<p>Fraction lost per cycle $= 1 - 0.5^{0.1} = 0.0670$, so $Q = 2\pi/0.067 = ${f(2 * Math.PI / (1 - Math.pow(0.5, 2 / 20)))}$.</p>` },
    { level: 'olympiad', type: 'num', title: 'Physical pendulum', q: R`<p>A uniform metre rule swings about a pivot 0.20 m from one end. Find its period.</p>`, answer: 2 * Math.PI * Math.sqrt((1 / 12 + 0.09) / (g * 0.3)), tol: 0.01, unit: 's', hints: [R`$T = 2\pi\sqrt{I/mgd}$, $d = 0.30$ m, $I = mL^2/12 + md^2$.`], solution: R`<p>$I/m = 0.0833 + 0.09 = 0.1733$; $T = 2\pi\sqrt{0.1733/2.94} = ${f(2 * Math.PI * Math.sqrt((1 / 12 + 0.09) / (g * 0.3)))}$ s.</p>` }
  ]);
  X('fluids', [
    { level: 'concept', type: 'mcq', title: 'Ice in a glass', q: R`<p>An ice cube floats in a full glass of water. When it melts, the water level…</p>`, options: ['Rises and spills', 'Falls', 'Stays the same', 'Depends on the temperature'], answer: 2, hints: [R`Floating ice displaces its own weight.`], solution: R`<p>Unchanged: the meltwater exactly fills the volume the ice displaced.</p>` },
    { level: 'core', type: 'num', title: 'Pressure at depth', q: R`<p>What is the absolute pressure 25 m below the sea surface (ρ = 1025 kg/m³, $P_0 = 101$ kPa), in kPa?</p>`, answer: 101 + 1025 * g * 25 / 1000, tol: 0.005, unit: 'kPa', hints: [R`$P_0 + \rho gh$.`], solution: R`<p>${f(101 + 1025 * g * 25 / 1000)} kPa, about 3.5 atmospheres.</p>` },
    { level: 'core', type: 'num', title: 'Venturi', q: R`<p>Water flows at 2.0 m/s in a 4.0 cm pipe that narrows to 2.0 cm. What is the pressure drop, in kPa?</p>`, answer: 0.5 * 1000 * (64 - 4) / 1000, tol: 0.01, unit: 'kPa', hints: [R`Speed rises fourfold.`], solution: R`<p>$v_2 = 8$ m/s; $\Delta P = \tfrac12\rho(v_2^2 - v_1^2) = 30$ kPa.</p>` },
    { level: 'olympiad', type: 'num', title: 'Stokes settling', q: R`<p>A sand grain of radius 50 μm and density 2650 kg/m³ settles in water (viscosity $1.0\times10^{-3}$ Pa s). Find its terminal speed in mm/s using Stokes’ law.</p>`, answer: 2 / 9 * 1650 * g * 2.5e-9 / 1e-3 * 1000, tol: 0.01, unit: 'mm/s', hints: [R`$v = \frac{2}{9}\frac{(\rho_s - \rho)gr^2}{\eta}$.`], solution: R`<p>$v = ${f(2 / 9 * 1650 * g * 2.5e-9 / 1e-3 * 1000)}$ mm/s.</p>` }
  ]);
  X('waves', [
    { level: 'concept', type: 'mcq', title: 'Open and closed pipes', q: R`<p>A pipe closed at one end produces…</p>`, options: ['All harmonics', 'Only odd harmonics', 'Only even harmonics', 'No standing waves'], answer: 1, hints: [R`Node at the closed end, antinode at the open end.`], solution: R`<p>Only odd harmonics: $L = (2n - 1)\lambda/4$.</p>` },
    { level: 'core', type: 'num', title: 'String frequency', q: R`<p>A 0.65 m guitar string of linear density 1.2 g/m is under 75 N tension. Find its fundamental frequency.</p>`, answer: Math.sqrt(75 / 0.0012) / (2 * 0.65), tol: 0.01, unit: 'Hz', hints: [R`$f = \frac{1}{2L}\sqrt{T/\mu}$.`], solution: R`<p>${f(Math.sqrt(75 / 0.0012) / (2 * 0.65))} Hz.</p>` },
    { level: 'core', type: 'num', title: 'Decibels', q: R`<p>Ten identical machines each produce 80 dB. What is the level with all ten running?</p>`, answer: 90, tol: 0.002, unit: 'dB', hints: [R`Intensities add.`], solution: R`<p>$80 + 10\log_{10}10 = 90$ dB.</p>` },
    { level: 'olympiad', type: 'num', title: 'Moving source and observer', q: R`<p>An ambulance at 30 m/s with a 700 Hz siren approaches a cyclist riding towards it at 8 m/s. What frequency does the cyclist hear ($v = 340$ m/s)?</p>`, answer: 700 * (340 + 8) / (340 - 30), tol: 0.005, unit: 'Hz', hints: [R`$f' = f\frac{v + v_o}{v - v_s}$.`], solution: R`<p>$700\times348/310 = ${f(700 * (340 + 8) / (340 - 30))}$ Hz.</p>` }
  ]);
  X('thermal', [
    { level: 'concept', type: 'mcq', title: 'Same temperature', q: R`<p>Hydrogen and oxygen gas are at the same temperature. Which has the larger average kinetic energy per molecule?</p>`, options: ['Hydrogen', 'Oxygen', 'They are equal', 'It depends on pressure'], answer: 2, hints: [R`$\tfrac32kT$.`], solution: R`<p>Equal; hydrogen molecules are faster because they are lighter.</p>` },
    { level: 'core', type: 'num', title: 'Mixing water', q: R`<p>200 g of water at 80 °C is mixed with 300 g at 20 °C. What is the final temperature?</p>`, answer: (200 * 80 + 300 * 20) / 500, tol: 0.005, unit: '°C', hints: [R`Weighted average.`], solution: R`<p>${f((200 * 80 + 300 * 20) / 500)} °C.</p>` },
    { level: 'core', type: 'num', title: 'Melting ice', q: R`<p>How much heat melts 50 g of ice at 0 °C and warms it to 20 °C? ($L_f = 334$ J/g, $c = 4.18$ J g⁻¹ K⁻¹.)</p>`, answer: 50 * 334 + 50 * 4.18 * 20, tol: 0.005, unit: 'J', hints: [R`Latent plus sensible heat.`], solution: R`<p>$16\,700 + 4180 = ${f(50 * 334 + 50 * 4.18 * 20, 4)}$ J.</p>` },
    { level: 'olympiad', type: 'num', title: 'Radiating sphere', q: R`<p>A black sphere of radius 5 cm at 600 K sits in a room at 300 K. What net power does it radiate?</p>`, answer: 5.67e-8 * 4 * Math.PI * 0.0025 * (Math.pow(600, 4) - Math.pow(300, 4)), tol: 0.01, unit: 'W', hints: [R`$\sigma A(T^4 - T_0^4)$.`], solution: R`<p>$P = ${f(5.67e-8 * 4 * Math.PI * 0.0025 * (Math.pow(600, 4) - Math.pow(300, 4)))}$ W.</p>` }
  ]);
  X('thermodynamics', [
    { level: 'concept', type: 'mcq', title: 'Adiabatic compression', q: R`<p>A gas is compressed quickly with no heat exchange. Its temperature…</p>`, options: ['Falls', 'Rises', 'Stays the same', 'Depends on the gas only'], answer: 1, hints: [R`$\Delta U = W$ on the gas.`], solution: R`<p>Rises: the work done on it becomes internal energy (as in a diesel engine).</p>` },
    { level: 'core', type: 'num', title: 'Carnot limit', q: R`<p>A power station boiler runs at 560 °C and its condenser at 30 °C. What is the Carnot efficiency, in %?</p>`, answer: 100 * (1 - 303.15 / 833.15), tol: 0.005, unit: '%', hints: [R`Use kelvin.`], solution: R`<p>$1 - 303/833 = ${f(100 * (1 - 303.15 / 833.15))}\%$.</p>` },
    { level: 'core', type: 'num', title: 'Isothermal work', q: R`<p>2.0 mol of ideal gas expands isothermally at 300 K from 10 L to 30 L. How much work does it do?</p>`, answer: 2 * 8.314 * 300 * Math.log(3), tol: 0.005, unit: 'J', hints: [R`$nRT\ln(V_2/V_1)$.`], solution: R`<p>${f(2 * 8.314 * 300 * Math.log(3), 4)} J.</p>` },
    { level: 'olympiad', type: 'num', title: 'Heat pump', q: R`<p>An ideal heat pump keeps a house at 20 °C when it is 0 °C outside. How many joules of heat are delivered per joule of electricity?</p>`, answer: 293.15 / 20, tol: 0.005, unit: '', hints: [R`$\text{COP} = T_h/(T_h - T_c)$.`], solution: R`<p>${f(293.15 / 20)}; real heat pumps manage 3 to 4.</p>` }
  ]);
  X('electrostatics', [
    { level: 'concept', type: 'mcq', title: 'Inside a conductor', q: R`<p>In electrostatic equilibrium, the electric field inside a solid conductor is…</p>`, options: ['Largest at the centre', 'Zero', 'Equal to the surface field', 'Radial'], answer: 1, hints: [R`Free charges would move otherwise.`], solution: R`<p>Zero; this is why a Faraday cage shields its contents.</p>` },
    { level: 'core', type: 'num', title: 'Coulomb force', q: R`<p>Two charges of +3.0 μC and −5.0 μC are 0.20 m apart. Find the magnitude of the force.</p>`, answer: 8.988e9 * 3e-6 * 5e-6 / 0.04, tol: 0.005, unit: 'N', hints: [R`$kq_1q_2/r^2$.`], solution: R`<p>${f(8.988e9 * 3e-6 * 5e-6 / 0.04)} N, attractive.</p>` },
    { level: 'core', type: 'num', title: 'Electron gun', q: R`<p>An electron is accelerated from rest through 2.0 kV. What is its speed, in units of 10⁷ m/s?</p>`, answer: Math.sqrt(2 * 1.602e-19 * 2000 / 9.109e-31) / 1e7, tol: 0.005, unit: '×10⁷ m/s', hints: [R`$eV = \tfrac12mv^2$.`], solution: R`<p>$v = ${f(Math.sqrt(2 * 1.602e-19 * 2000 / 9.109e-31) / 1e7)}\times10^7$ m/s.</p>` },
    { level: 'olympiad', type: 'num', title: 'Equilibrium point', q: R`<p>Charges +4q and +q are 0.30 m apart. Where between them is the field zero (distance from +4q)?</p>`, answer: 0.2, tol: 0.005, unit: 'm', hints: [R`$4/x^2 = 1/(0.3 - x)^2$.`], solution: R`<p>$2/x = 1/(0.3 - x)$ gives $x = 0.20$ m.</p>` }
  ]);
  X('circuits', [
    { level: 'concept', type: 'mcq', title: 'Bulbs in series', q: R`<p>A second identical bulb is added in series with the first. The first bulb becomes…</p>`, options: ['Brighter', 'Dimmer', 'Unchanged', 'Off'], answer: 1, hints: [R`Resistance doubles.`], solution: R`<p>Dimmer: current halves, power falls to a quarter.</p>` },
    { level: 'core', type: 'num', title: 'Parallel resistors', q: R`<p>Resistors of 6 Ω, 3 Ω and 2 Ω are connected in parallel. What is the equivalent resistance?</p>`, answer: 1, tol: 0.005, unit: 'Ω', hints: [R`$1/6 + 1/3 + 1/2$.`], solution: R`<p>1 Ω.</p>` },
    { level: 'core', type: 'num', title: 'RC time', q: R`<p>A 470 μF capacitor charges through 10 kΩ. How long until it reaches 90% of the supply voltage?</p>`, answer: 470e-6 * 1e4 * Math.log(10), tol: 0.005, unit: 's', hints: [R`$t = RC\ln10$.`], solution: R`<p>$4.7\times2.303 = ${f(470e-6 * 1e4 * Math.log(10))}$ s.</p>` },
    { level: 'olympiad', type: 'num', title: 'Wheatstone bridge', q: R`<p>A bridge has $R_1 = 100$ Ω, $R_2 = 150$ Ω, $R_3 = 220$ Ω. What unknown $R_x$ balances it ($R_1/R_2 = R_3/R_x$)?</p>`, answer: 330, tol: 0.005, unit: 'Ω', hints: [R`Cross-multiply.`], solution: R`<p>$R_x = 150\times220/100 = 330$ Ω.</p>` }
  ]);
  X('magnetism', [
    { level: 'concept', type: 'mcq', title: 'Force on a charge', q: R`<p>A charged particle moves parallel to a magnetic field. The magnetic force on it is…</p>`, options: ['Maximum', 'Zero', 'Along the field', 'Opposite to the velocity'], answer: 1, hints: [R`$q\vec v\times\vec B$.`], solution: R`<p>Zero.</p>` },
    { level: 'core', type: 'num', title: 'Cyclotron radius', q: R`<p>A proton at $3.0\times10^6$ m/s moves perpendicular to a 0.50 T field. What is its orbit radius, in cm?</p>`, answer: 1.673e-27 * 3e6 / (1.602e-19 * 0.5) * 100, tol: 0.005, unit: 'cm', hints: [R`$r = mv/qB$.`], solution: R`<p>${f(1.673e-27 * 3e6 / (1.602e-19 * 0.5) * 100)} cm.</p>` },
    { level: 'core', type: 'num', title: 'Field of a wire', q: R`<p>What is the magnetic field 2.0 cm from a long wire carrying 15 A, in μT?</p>`, answer: 2e-7 * 15 / 0.02 * 1e6, tol: 0.005, unit: 'μT', hints: [R`$\mu_0I/2\pi r$.`], solution: R`<p>150 μT, three times Earth’s field.</p>` },
    { level: 'olympiad', type: 'num', title: 'Velocity selector', q: R`<p>Crossed fields of $E = 4.0\times10^4$ V/m and $B = 0.080$ T pass ions undeflected at what speed, in km/s?</p>`, answer: 4e4 / 0.08 / 1000, tol: 0.005, unit: 'km/s', hints: [R`$qE = qvB$.`], solution: R`<p>$v = E/B = 500$ km/s, whatever the charge or mass.</p>` }
  ]);
  X('induction', [
    { level: 'concept', type: 'mcq', title: 'Lenz’s law', q: R`<p>A magnet's north pole is pushed into a coil. The induced current makes the near end of the coil a…</p>`, options: ['North pole', 'South pole', 'Neither', 'It alternates'], answer: 0, hints: [R`It opposes the change.`], solution: R`<p>A north pole, repelling the approaching magnet.</p>` },
    { level: 'core', type: 'num', title: 'Generator EMF', q: R`<p>A 200-turn coil of area 0.010 m² rotates at 50 Hz in a 0.20 T field. What is the peak EMF?</p>`, answer: 200 * 0.01 * 0.2 * 2 * Math.PI * 50, tol: 0.005, unit: 'V', hints: [R`$NAB\omega$.`], solution: R`<p>${f(200 * 0.01 * 0.2 * 2 * Math.PI * 50)} V.</p>` },
    { level: 'core', type: 'num', title: 'Transformer', q: R`<p>A transformer steps 230 V down to 12 V. If the primary has 1150 turns, how many turns does the secondary have?</p>`, answer: 60, tol: 0.005, unit: '', hints: [R`$V_s/V_p = N_s/N_p$.`], solution: R`<p>60 turns.</p>` },
    { level: 'olympiad', type: 'num', title: 'Resonance', q: R`<p>A series circuit has $L = 25$ mH and $C = 10$ μF. What is its resonant frequency?</p>`, answer: 1 / (2 * Math.PI * Math.sqrt(0.025 * 1e-5)), tol: 0.005, unit: 'Hz', hints: [R`$f = 1/2\pi\sqrt{LC}$.`], solution: R`<p>${f(1 / (2 * Math.PI * Math.sqrt(0.025 * 1e-5)))} Hz.</p>` }
  ]);
  X('geometric-optics', [
    { level: 'concept', type: 'mcq', title: 'Diverging lens', q: R`<p>A diverging lens always forms an image that is…</p>`, options: ['Real and inverted', 'Virtual, upright and smaller', 'Virtual and magnified', 'Real and magnified'], answer: 1, hints: [R`Ray diagram.`], solution: R`<p>Virtual, upright and diminished.</p>` },
    { level: 'core', type: 'num', title: 'Lens image', q: R`<p>An object is 30 cm from a converging lens of focal length 20 cm. Where is the image?</p>`, answer: 60, tol: 0.005, unit: 'cm', hints: [R`$1/v = 1/f - 1/u$.`], solution: R`<p>$1/v = 1/20 - 1/30$, $v = 60$ cm, real and twice the size.</p>` },
    { level: 'core', type: 'num', title: 'Critical angle', q: R`<p>Find the critical angle for light going from diamond ($n = 2.42$) into air.</p>`, answer: Math.asin(1 / 2.42) * 180 / Math.PI, tol: 0.005, unit: '°', hints: [R`$\sin\theta_c = 1/n$.`], solution: R`<p>${f(Math.asin(1 / 2.42) * 180 / Math.PI)}°, which is why diamonds sparkle.</p>` },
    { level: 'olympiad', type: 'num', title: 'Apparent depth', q: R`<p>A coin lies at the bottom of a pool 2.4 m deep ($n = 1.33$). How deep does it appear when viewed from directly above?</p>`, answer: 2.4 / 1.33, tol: 0.005, unit: 'm', hints: [R`Small angles: real/apparent $= n$.`], solution: R`<p>${f(2.4 / 1.33)} m.</p>` }
  ]);
  X('wave-optics', [
    { level: 'concept', type: 'mcq', title: 'Wider slits', q: R`<p>In a double-slit experiment, the slit separation is doubled. The fringe spacing…</p>`, options: ['Doubles', 'Halves', 'Is unchanged', 'Quadruples'], answer: 1, hints: [R`$\Delta y = \lambda L/d$.`], solution: R`<p>Halves.</p>` },
    { level: 'core', type: 'num', title: 'Grating', q: R`<p>A grating with 600 lines/mm is lit with 589 nm light. At what angle is the second order?</p>`, answer: Math.asin(2 * 589e-9 * 6e5) * 180 / Math.PI, tol: 0.005, unit: '°', hints: [R`$d\sin\theta = m\lambda$, $d = 1/600$ mm.`], solution: R`<p>$\sin\theta = 0.7068$, $\theta = ${f(Math.asin(2 * 589e-9 * 6e5) * 180 / Math.PI)}^\circ$.</p>` },
    { level: 'core', type: 'num', title: 'Anti-reflection coating', q: R`<p>What is the thinnest MgF₂ coating ($n = 1.38$) on glass that cancels reflection of 550 nm light?</p>`, answer: 550 / (4 * 1.38), tol: 0.005, unit: 'nm', hints: [R`Both reflections flip, so $2nd = \lambda/2$.`], solution: R`<p>$d = \lambda/4n = ${f(550 / (4 * 1.38))}$ nm.</p>` },
    { level: 'olympiad', type: 'num', title: 'Single-slit width', q: R`<p>The central maximum of a single-slit pattern of 633 nm light is 8.0 mm wide on a screen 2.0 m away. How wide is the slit, in mm?</p>`, answer: 2 * 633e-9 * 2 / 8e-3 * 1000, tol: 0.005, unit: 'mm', hints: [R`First minima at $\sin\theta = \lambda/a$.`], solution: R`<p>Half-width 4.0 mm, so $a = \lambda L/0.004 = ${f(2 * 633e-9 * 2 / 8e-3 * 1000)}$ mm.</p>` }
  ]);
  X('relativity', [
    { level: 'concept', type: 'mcq', title: 'Muons', q: R`<p>Muons made high in the atmosphere reach the ground although their lifetime is only 2.2 μs. In the muon’s frame, this is explained by…</p>`, options: ['Time dilation', 'Length contraction of the atmosphere', 'Their mass increase', 'Gravity'], answer: 1, hints: [R`In its own frame the muon’s clock is normal.`], solution: R`<p>Length contraction: the atmosphere is thin in the muon frame. (Earth observers say time dilation.)</p>` },
    { level: 'core', type: 'num', title: 'Lorentz factor', q: R`<p>Find γ for a speed of 0.95c.</p>`, answer: 1 / Math.sqrt(1 - 0.95 * 0.95), tol: 0.005, unit: '', hints: [R`$1/\sqrt{1 - v^2/c^2}$.`], solution: R`<p>${f(1 / Math.sqrt(1 - 0.95 * 0.95))}.</p>` },
    { level: 'core', type: 'num', title: 'Velocity addition', q: R`<p>A ship moving at 0.6c fires a probe forward at 0.7c relative to the ship. How fast is the probe in the original frame (in units of c)?</p>`, answer: 1.3 / 1.42, tol: 0.005, unit: 'c', hints: [R`$(u + v)/(1 + uv/c^2)$.`], solution: R`<p>$1.3/1.42 = ${f(1.3 / 1.42)}c$.</p>` },
    { level: 'olympiad', type: 'num', title: 'Twin trip', q: R`<p>A twin travels to a star 6 light-years away at 0.8c and returns. How many years younger is she than her sibling on return?</p>`, answer: 15 - 9, tol: 0.005, unit: 'years', hints: [R`Earth time 15 years, γ = 5/3.`], solution: R`<p>Earth: $12/0.8 = 15$ years; traveller: $15/\gamma = 9$ years. Difference 6 years.</p>` }
  ]);
  X('quantum', [
    { level: 'concept', type: 'mcq', title: 'Brighter light', q: R`<p>In the photoelectric effect, increasing the intensity of light above threshold increases…</p>`, options: ['The maximum kinetic energy of electrons', 'The number of electrons per second', 'The threshold frequency', 'The work function'], answer: 1, hints: [R`More photons, same energy each.`], solution: R`<p>The number of photoelectrons per second.</p>` },
    { level: 'core', type: 'num', title: 'Photoelectron energy', q: R`<p>Light of 250 nm falls on a metal with work function 4.3 eV. What is the maximum kinetic energy of the electrons, in eV?</p>`, answer: 1240 / 250 - 4.3, tol: 0.01, unit: 'eV', hints: [R`$hc/\lambda - \phi$.`], solution: R`<p>$4.96 - 4.30 = ${f(1240 / 250 - 4.3)}$ eV.</p>` },
    { level: 'core', type: 'num', title: 'de Broglie', q: R`<p>Find the de Broglie wavelength of an electron accelerated through 100 V, in nm.</p>`, answer: 6.626e-34 / Math.sqrt(2 * 9.109e-31 * 1.602e-19 * 100) * 1e9, tol: 0.005, unit: 'nm', hints: [R`$\lambda = h/\sqrt{2meV}$.`], solution: R`<p>${f(6.626e-34 / Math.sqrt(2 * 9.109e-31 * 1.602e-19 * 100) * 1e9)} nm, comparable to atomic spacings.</p>` },
    { level: 'olympiad', type: 'num', title: 'Hydrogen line', q: R`<p>What wavelength is emitted when hydrogen drops from n = 4 to n = 2, in nm? ($E_n = -13.6/n^2$ eV.)</p>`, answer: 1240 / (13.6 * (1 / 4 - 1 / 16)), tol: 0.005, unit: 'nm', hints: [R`$\Delta E = 2.55$ eV.`], solution: R`<p>${f(1240 / (13.6 * (1 / 4 - 1 / 16)))} nm: the blue-green Hβ line.</p>` }
  ]);
  X('nuclear', [
    { level: 'concept', type: 'mcq', title: 'Alpha decay', q: R`<p>In alpha decay, the mass number and atomic number change by…</p>`, options: ['−4 and −2', '−2 and −4', '0 and +1', '−4 and 0'], answer: 0, hints: [R`An alpha is ⁴He.`], solution: R`<p>A falls by 4, Z by 2.</p>` },
    { level: 'core', type: 'num', title: 'Carbon dating', q: R`<p>A bone has 22% of the ¹⁴C of living tissue. Using a half-life of 5730 years, how old is it?</p>`, answer: 5730 * Math.log(1 / 0.22) / Math.log(2), tol: 0.005, unit: 'years', hints: [R`$t = t_{1/2}\log_2(N_0/N)$.`], solution: R`<p>${f(5730 * Math.log(1 / 0.22) / Math.log(2), 4)} years.</p>` },
    { level: 'core', type: 'num', title: 'Fusion energy', q: R`<p>D + T → ⁴He + n releases 17.6 MeV. How much energy, in TJ, is released by fusing 1 g of D–T fuel (5 g/mol per reaction pair)?</p>`, answer: 17.6e6 * 1.602e-19 * 6.022e23 / 5 / 1e12, tol: 0.01, unit: 'TJ', hints: [R`0.2 mol of reactions.`], solution: R`<p>${f(17.6e6 * 1.602e-19 * 6.022e23 / 5 / 1e12)} TJ: about 80 tonnes of TNT per gram.</p>` },
    { level: 'olympiad', type: 'num', title: 'Activity', q: R`<p>What is the activity of 1.0 μg of ⁶⁰Co (half-life 5.27 years), in units of 10⁷ Bq?</p>`, answer: Math.log(2) / (5.27 * 3.156e7) * (1e-6 / 60 * 6.022e23) / 1e7, tol: 0.01, unit: '×10⁷ Bq', hints: [R`$A = \lambda N$.`], solution: R`<p>$N = 1.00\times10^{16}$; $\lambda = 4.17\times10^{-9}$ s⁻¹; $A = ${f(Math.log(2) / (5.27 * 3.156e7) * (1e-6 / 60 * 6.022e23) / 1e7)}\times10^7$ Bq.</p>` }
  ]);
  X('analytical', [
    { level: 'concept', type: 'mcq', title: 'Cyclic coordinate', q: R`<p>If the Lagrangian does not depend on a coordinate $q$, then…</p>`, options: ['$q$ is constant', 'Its conjugate momentum is conserved', 'The energy is zero', 'The motion is periodic'], answer: 1, hints: [R`Euler–Lagrange: $\dot p = \partial L/\partial q$.`], solution: R`<p>$p_q = \partial L/\partial\dot q$ is conserved.</p>` },
    { level: 'core', type: 'num', title: 'Bead on a hoop', q: R`<p>A bead slides on a hoop of radius 0.2 m spinning about a vertical diameter at 10 rad/s. At what angle from the bottom does it sit in equilibrium?</p>`, answer: Math.acos(g / (100 * 0.2)) * 180 / Math.PI, tol: 0.005, unit: '°', hints: [R`$\cos\theta = g/\omega^2R$.`], solution: R`<p>$\cos\theta = 9.8/20$, $\theta = ${f(Math.acos(g / (100 * 0.2)) * 180 / Math.PI)}^\circ$.</p>` },
    { level: 'core', type: 'num', title: 'Small oscillations', q: R`<p>A particle of mass 0.5 kg moves in $U(x) = 2x^4 - 4x^2$ (J, m). Find the period of small oscillations about a minimum.</p>`, answer: 2 * Math.PI / Math.sqrt(16 / 0.5), tol: 0.005, unit: 's', hints: [R`Minima at $x = \pm1$; $U'' = 24x^2 - 8 = 16$.`], solution: R`<p>$\omega = \sqrt{16/0.5}$, $T = ${f(2 * Math.PI / Math.sqrt(16 / 0.5))}$ s.</p>` },
    { level: 'olympiad', type: 'num', title: 'Brachistochrone time', q: R`<p>The time to slide down a cycloid from rest to its bottom is $\pi\sqrt{a/g}$, independent of the start. For $a = 1.0$ m, what is it?</p>`, answer: Math.PI * Math.sqrt(1 / g), tol: 0.005, unit: 's', hints: [R`Plug in.`], solution: R`<p>${f(Math.PI * Math.sqrt(1 / g))} s: the tautochrone property.</p>` }
  ]);
  X('astrophysics', [
    { level: 'concept', type: 'mcq', title: 'Redshift', q: R`<p>Distant galaxies show redshifts mostly because…</p>`, options: ['They are hot', 'Space is expanding', 'Of gravity of the Milky Way', 'Dust reddens them'], answer: 1, hints: [R`Hubble's law.`], solution: R`<p>The expansion of the universe.</p>` },
    { level: 'core', type: 'num', title: 'Sun’s temperature', q: R`<p>The solar flux at Earth is 1361 W/m². Using $R_\odot = 6.96\times10^8$ m and 1 AU = $1.496\times10^{11}$ m, find the Sun’s surface temperature.</p>`, answer: Math.pow(1361 * Math.pow(1.496e11 / 6.96e8, 2) / 5.67e-8, 0.25), tol: 0.005, unit: 'K', hints: [R`$\sigma T^4 = F(d/R)^2$.`], solution: R`<p>$T = ${f(Math.pow(1361 * Math.pow(1.496e11 / 6.96e8, 2) / 5.67e-8, 0.25), 4)}$ K.</p>` },
    { level: 'core', type: 'num', title: 'Hubble distance', q: R`<p>A galaxy recedes at 14 000 km/s. With $H_0 = 70$ km/s/Mpc, how far is it?</p>`, answer: 200, tol: 0.005, unit: 'Mpc', hints: [R`$v/H_0$.`], solution: R`<p>200 Mpc.</p>` },
    { level: 'olympiad', type: 'num', title: 'Eddington luminosity', q: R`<p>$L_{\text{Edd}} = 4\pi GMm_pc/\sigma_T$ with $\sigma_T = 6.65\times10^{-29}$ m². Find it for a 1 M☉ star, in units of 10³¹ W.</p>`, answer: 4 * Math.PI * 6.674e-11 * 1.989e30 * 1.673e-27 * 3e8 / 6.65e-29 / 1e31, tol: 0.01, unit: '×10³¹ W', hints: [R`Plug in.`], solution: R`<p>$${f(4 * Math.PI * 6.674e-11 * 1.989e30 * 1.673e-27 * 3e8 / 6.65e-29 / 1e31)}\times10^{31}$ W, about 33 000 L☉.</p>` }
  ]);
  X('experimental', [
    { level: 'concept', type: 'mcq', title: 'Precision versus accuracy', q: R`<p>Repeated readings cluster tightly but far from the true value. They are…</p>`, options: ['Accurate but imprecise', 'Precise but inaccurate', 'Both', 'Neither'], answer: 1, hints: [R`Systematic error.`], solution: R`<p>Precise (small scatter) but inaccurate (systematic offset).</p>` },
    { level: 'core', type: 'num', title: 'Combining uncertainties', q: R`<p>$g = 4\pi^2L/T^2$ with $L$ measured to 0.5% and $T$ to 0.4%. What is the percentage uncertainty in $g$ (independent errors added in quadrature)?</p>`, answer: Math.sqrt(0.25 + 0.64), tol: 0.01, unit: '%', hints: [R`$\sqrt{0.5^2 + (2\times0.4)^2}$.`], solution: R`<p>${f(Math.sqrt(0.25 + 0.64))}%.</p>` },
    { level: 'core', type: 'num', title: 'Standard error', q: R`<p>Sixteen readings have a standard deviation of 0.08 s. What is the standard error of the mean?</p>`, answer: 0.02, tol: 0.005, unit: 's', hints: [R`$\sigma/\sqrt N$.`], solution: R`<p>0.02 s.</p>` },
    { level: 'olympiad', type: 'num', title: 'Log–log slope', q: R`<p>Measurements give $y = 3.2$ at $x = 2.0$ and $y = 25.6$ at $x = 8.0$. If $y = Cx^n$, what is $n$?</p>`, answer: Math.log(8) / Math.log(4), tol: 0.005, unit: '', hints: [R`$n = \ln(y_2/y_1)/\ln(x_2/x_1)$.`], solution: R`<p>$\ln8/\ln4 = 1.5$.</p>` }
  ]);
})();
